                using(var fresh=new Scope(this,m.Path,null)){var freshStudy=(IMotionStudy)((IMotionStudyManager)fresh.Doc.Extension.GetMotionStudyManager()).GetMotionStudy(studyName);actual=StudyStates(fresh.Doc).Single(s=>s.name==studyName);if(Math.Abs(actual.time_s)>1e-8||freshStudy.IsPlaying||actual.type!=initial.type||actual.fps!=initial.fps||Math.Abs(actual.duration_s-initial.duration_s)>1e-8)throw new CadFault("STUDY_RESET_UNVERIFIED","保存副本重开后的零时刻或设置未通过；不将缓存姿态当作零位。",new{stage=stage,actual=actual});finalPoses=Transforms(fresh.Doc);cachedDeviation=ResetPoseEvidence.CachedDeviation(Json.Deserialize<Dictionary<string,object>>(Json.Serialize(PoseChange(beforeReopenPoses,finalPoses))));trace.Add(new{stage=stage,actual=actual,cached_memory_pose_deviation=cachedDeviation,pose_change_scope="post_save_cached_memory_vs_reopened_live_document",pose_source="native_reopened_saved_zero_no_transform_forcing"});}
