                return new{reset_pose_reopen_proof=resetProof,reset_checkpoint_id=resetCheckpoint["checkpoint_id"],model_id=id,study=studyName,time_s=actual.time_s,previous_time_s=initial.time_s,target_time_s=0,pose_change=poseChange,pose_change_scope="pre_operation_live_vs_reopened_saved_document_not_zero_pose_oracle",cached_memory_pose_deviation=cachedDeviation,warning_codes=ResetPoseEvidence.WarningCodes(cachedDeviation),committed_pose_validation=committedPoseValidation,committed_state_scope="current_live_document_matches_verified_reopened_document_after_independent_checkpoint_proof",client_action_required=false,operation_state="committed",restoration_scope="document_context_only_after_successful_reset",target_pose_validation="explicit_frame_reselection_saved_model_reopen_and_checkpoint_proof_no_independent_frame0_oracle",expected_pose_source="native_reopened_saved_zero_then_independent_checkpoint_reopen",independent_frame0_oracle=false,pre_operation_pose_restored=previousPoseRestored,restoration_status_semantics="legacy_status_confirms_safe_completion_not_previous_pose",active=actual.active,previous_checkpoint_id=checkpoint,results_invalidated=true,invalidates_previous_baselines=true,baseline_invalidation_scope="all_existing_runs_for_this_registered_model_revision_and_file_hashes_rechecked_no_automatic_rebinding",restoration_status="restored",source_files_unchanged=true,recalculated_for_reset=calculated,study_settings_preserved=true,settings_unchanged=true,settings_modified_by_request=false,settings_preserved_scope="unchanged_from_pre_operation_settings_not_a_restoration_assertion",reset_budget=StudyCacheBudget.Describe(initial.duration_s,initial.fps),native_steps=trace,save_observation=SaveObservation(m)};
